import React, { useState, useContext } from "react";
import { AuthContext } from "../../../Context/AuthContext";
import "./ModalLogin.css";
import { useNavigate } from "react-router-dom";

const ModalLogin = ({ show, handleClose }) => {
    const { login } = useContext(AuthContext);
    const [formModalLogin, setFormModalLogin] = useState({
        accountname: "",
        password: "",
    });

    const navigate = useNavigate();

    if (!show) return null;

    const handleRegisterClick = () => {
        handleClose();
        navigate("/register");
    };

    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) {
            handleClose();
        }
    };

    const handleSubmitLogin = async (e) => {
        e.preventDefault();
        if (!formModalLogin.accountname || !formModalLogin.password) {
            alert("Vui lòng nhập đầy đủ thông tin");
            return;
        }
        try {
            const data = await login(formModalLogin);
            alert("Login successful!");
            setFormModalLogin({ accountname: "", password: "" });
            handleClose();
            navigate("/");
        } catch (error) {
            console.error("Login failed:", error);
            alert("Login failed:" + (error.response?.data?.message || error.message));
        }
    };

    return (
        <div className="modal-backdrop-custom" onClick={handleBackdropClick}>
            <div className="modal-dialog modal-lg modal-dialog-centered">
                <div className="modal-content border-0 rounded-4 overflow-hidden shadow-lg">
                    <div className="modal-body p-0">
                        <div className="row g-0">
                            {/* Left Side */}
                            <div className="col-md-5 modal-left-gradient d-flex flex-column justify-content-center align-items-center text-white p-5">
                                <div className="text-center">
                                    <h2 className="fw-bold mb-3 display-6">ĐĂNG KÝ</h2>
                                    <p className="mb-4 fs-6">
                                        Bạn chưa có tài khoản, đăng ký ngay!
                                    </p>
                                    <button
                                        className="btn btn-outline-light btn-lg px-4 py-2 rounded-2 fw-semibold border-2"
                                        onClick={handleRegisterClick}
                                    >
                                        ĐĂNG KÝ TÀI KHOẢN MỚI
                                    </button>
                                </div>
                            </div>

                            {/* Right Side */}
                            <div className="col-md-7 bg-white p-5 position-relative">
                                {/* Close Button */}
                                <button
                                    type="button"
                                    className="btn-close position-absolute top-0 end-0 m-3"
                                    onClick={handleClose}
                                ></button>

                                <div className="login-form-container">
                                    <h3 className="fw-bold mb-4 text-dark text-center">
                                        ĐĂNG NHẬP
                                    </h3>

                                    <form onSubmit={handleSubmitLogin}>
                                        {/* Username */}
                                        <div className="mb-3">
                                            <label className="form-label fw-semibold text-dark mb-2">
                                                Tên tài khoản *
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control form-control-lg bg-light border-0 rounded-3 px-3"
                                                placeholder="Nhập tên tài khoản"
                                                name="accountname"
                                                autoComplete="accountname"
                                                value={formModalLogin.accountname}
                                                onChange={(e) =>
                                                    setFormModalLogin({
                                                        ...formModalLogin,
                                                        accountname: e.target.value,
                                                    })
                                                }
                                            />
                                        </div>

                                        {/* Password */}
                                        <div className="mb-3">
                                            <label className="form-label fw-semibold text-dark mb-2">
                                                Mật khẩu *
                                            </label>
                                            <input
                                                type="password"
                                                className="form-control form-control-lg bg-light border-0 rounded-3 px-3"
                                                placeholder="••••••••"
                                                name="password"
                                                autoComplete="current-password"
                                                value={formModalLogin.password}
                                                onChange={(e) =>
                                                    setFormModalLogin({
                                                        ...formModalLogin,
                                                        password: e.target.value,
                                                    })
                                                }
                                            />
                                        </div>

                                        {/* Remember */}
                                        <div className="form-check mb-3">
                                            <input
                                                className="form-check-input"
                                                type="checkbox"
                                                id="rememberPassword"
                                            />
                                            <label
                                                className="form-check-label text-dark"
                                                htmlFor="rememberPassword"
                                            >
                                                Ghi nhớ mật khẩu
                                            </label>
                                        </div>

                                        {/* Login Btn */}
                                        <button
                                            type="submit"
                                            className="btn btn-warning btn-lg w-100 fw-bold rounded-3 mb-3 text-white login-btn"
                                        >
                                            ĐĂNG NHẬP
                                        </button>

                                        {/* Forgot */}
                                        <div className="text-center mb-4">
                                            <a
                                                href="/forgot-password"
                                                className="text-decoration-none text-muted"
                                            >
                                                Quên mật khẩu?
                                            </a>
                                        </div>
                                    </form>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Social Footer */}
                    <div className="modal-footer bg-white border-0 flex-column">
                        <p className="text-muted mb-3">Hoặc đăng nhập bằng</p>
                        <div className="d-flex justify-content-center gap-3 flex-wrap">
                            <button
                                type="button"
                                className="btn btn-facebook fw-semibold rounded-pill d-flex align-items-center justify-content-center"
                            >
                                <i className="fab fa-facebook-f me-2"></i>
                                Facebook
                            </button>
                            <button
                                type="button"
                                className="btn btn-google fw-semibold rounded-pill d-flex align-items-center justify-content-center"
                            >
                                <i className="fab fa-google me-2"></i>
                                Google
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ModalLogin;
